$ErrorActionPreference='Stop'
$project='C:\Projects\gympro-api'
$bin='C:\Program Files\PostgreSQL\18\bin'
$git='C:\Program Files\Git\cmd\git.exe'
$rehearsal='C:\Projects\gympro-backups\ledger-adoption-rehearsal-20261025221534_969fa1'
$stamp=(Get-Date -Format 'yyyyMMddHHmmss')+'_'+[guid]::NewGuid().ToString('N').Substring(0,6)
$copy='gympro_adopt_20261025222923_6531ec';$reference='gympro_bootstrap_20261025222923_6531ec'
$report=Join-Path 'C:\Projects\gympro-backups' ('live-ledger-resume-'+$stamp)
$createdCopy=$false;$createdReference=$false;$success=$false;$liveCommitted=$false
$oldPassword=$env:PGPASSWORD;$oldOptions=$env:PGOPTIONS;$oldSsl=$env:PGSSLMODE
function Run([string]$Exe,[string[]]$Arguments,[string]$Step){
 Write-Host "CHECK: $Step" -ForegroundColor Cyan
 $old=$ErrorActionPreference
 try{$ErrorActionPreference='Continue';& $Exe @Arguments;$code=$LASTEXITCODE}finally{$ErrorActionPreference=$old}
 [IO.File]::WriteAllText((Join-Path $report ($Step+'.exit-code.txt')),[string]$code)
 if($null -eq $code -or $code -ne 0){throw "Step failed: $Step (exit $code)"}
}
try{
 Set-Location $project
 $previous=Get-Content 'C:\Projects\gympro-backups\live-ledger-adoption-20261025222923_6531ec\working-database\live-adoption-results.json' -Raw | ConvertFrom-Json
 if($previous.committed -ne $false){throw 'Original attempt does not show an uncommitted transaction; stop for review.'}
 if(@(Get-NetTCPConnection -LocalPort 3000 -State Listen -ErrorAction SilentlyContinue).Count){throw 'Stop your Nest/operator API with Ctrl+C before this controlled adoption. Also stop scheduled application jobs.'}
 foreach($exe in @('pg_dump.exe','pg_restore.exe','createdb.exe','dropdb.exe','psql.exe')){if(-not(Test-Path (Join-Path $bin $exe))){throw "Missing PostgreSQL tool: $exe"}}
 $prior=Get-Content (Join-Path $project 'docs\completion\ledger-adoption-rehearsal-summary.json') -Raw | ConvertFrom-Json
 if($prior.checksPassed -ne 14 -or $prior.temporaryDatabasesRemoved -ne $true -or $prior.workingLedgerInstalled -ne $false -or $prior.reportFolder -ne $rehearsal){throw 'Verified rehearsal prerequisite is incomplete.'}
 & $git -C $project merge-base --is-ancestor 31ae525 HEAD
 if($LASTEXITCODE -ne 0){throw 'Required rehearsal checkpoint 31ae525 is not in this history.'}
 if((Get-FileHash (Join-Path $project 'tools\adoption-rehearsal\verify-and-adopt.mjs') -Algorithm SHA256).Hash.ToLowerInvariant() -ne '4f9725042306d002f3c38db000786d0eb4fa02982522c194c4c991485361142c'){throw 'Verified rehearsal source changed.'}
 New-Item -ItemType Directory -Path $report | Out-Null
 $payload=Join-Path $report 'payload';$zip=Join-Path $report 'payload.zip'
 [IO.File]::WriteAllBytes($zip,[Convert]::FromBase64String(''));Expand-Archive $zip $payload
 $review=Get-Content (Join-Path $payload 'readiness-manifest.json') -Raw | ConvertFrom-Json
 foreach($entry in $review.sourceHashes){if((Get-FileHash (Join-Path $project $entry.file) -Algorithm SHA256).Hash.ToLowerInvariant() -ne $entry.sha256){throw "Source changed since reviewed schema: $($entry.file)"}}
 $node=(Get-Command node.exe -ErrorAction Stop).Source
 $secure=Read-Host 'Local PostgreSQL postgres password' -AsSecureString;$ptr=[Runtime.InteropServices.Marshal]::SecureStringToBSTR($secure)
 try{$env:PGPASSWORD=[Runtime.InteropServices.Marshal]::PtrToStringBSTR($ptr)}finally{[Runtime.InteropServices.Marshal]::ZeroFreeBSTR($ptr);$secure.Dispose()}
 $env:PGOPTIONS=$null;$env:PGSSLMODE='disable';$connection=@('-h','127.0.0.1','-p','5432','-U','postgres','-w')
 $archive=Join-Path $report 'gympro-before-live-ledger.dump'
 Run (Join-Path $bin 'pg_dump.exe') ($connection+@('-d','gympro_saas','--format=custom','--file',$archive)) 'fresh-working-backup'
 Run (Join-Path $bin 'pg_restore.exe') @('--list','--file',(Join-Path $report 'archive-list.txt'),$archive) 'verify-archive-listing'
 (Get-FileHash $archive -Algorithm SHA256).Hash.ToLowerInvariant() | Set-Content (Join-Path $report 'database-backup.sha256') -Encoding ASCII
 # Reuse only the two databases retained by the failed, uncommitted adoption.
 $createdCopy=$true;$createdReference=$true
 Run $node @('--test',(Join-Path $payload 'reviewed-equivalence.test.mjs')) 'reviewed-equivalence-tests'
 $copyReport=Join-Path $report 'restored-copy';New-Item -ItemType Directory $copyReport | Out-Null
 Run $node @((Join-Path $payload 'verify-and-register.mjs'),$project,$copy,$reference,$copyReport,'rehearsal') 'verify-new-code-on-copy'
 $copyResults=Get-Content (Join-Path $copyReport 'live-adoption-results.json') -Raw | ConvertFrom-Json
 if($copyResults.success -ne $true -or $copyResults.checkCount -ne 9 -or $copyResults.mode -ne 'rehearsal'){throw 'Fresh-copy verification incomplete. Working database not adopted.'}
 $liveReport=Join-Path $report 'working-database';New-Item -ItemType Directory $liveReport | Out-Null
 Write-Host 'REGISTER: Working database ledger metadata only. Only exact reviewed representation pairs are accepted. Existing business functions will not be replayed.' -ForegroundColor Yellow
 Run $node @((Join-Path $payload 'verify-and-register.mjs'),$project,'gympro_saas',$reference,$liveReport,'live') 'register-working-ledger'
 $liveResults=Get-Content (Join-Path $liveReport 'live-adoption-results.json') -Raw | ConvertFrom-Json
 $liveCommitted=$liveResults.committed -eq $true
 if($liveResults.success -ne $true -or $liveResults.checkCount -ne 9 -or $liveResults.workingLedgerInstalled -ne $true -or $liveResults.businessDataChanged -ne $false -or $liveResults.businessFunctionsReplayed -ne $false){throw 'Live ledger evidence incomplete; inspect committed status before any retry.'}
 $success=$true
}catch{
 Write-Host ('FAIL: '+$_.Exception.Message) -ForegroundColor Red
 $statusPath=Join-Path $report 'working-database\live-adoption-results.json'
 if(Test-Path $statusPath){$status=Get-Content $statusPath -Raw | ConvertFrom-Json;$liveCommitted=$status.committed -eq $true}
}finally{
 if($success){try{
  if($createdCopy){Run (Join-Path $bin 'dropdb.exe') ($connection+@($copy)) 'remove-copy';$createdCopy=$false}
  if($createdReference){Run (Join-Path $bin 'dropdb.exe') ($connection+@($reference)) 'remove-reference';$createdReference=$false}
 }catch{$success=$false;Write-Host ('FAIL: '+$_.Exception.Message) -ForegroundColor Red}}
 $env:PGPASSWORD=$oldPassword;$env:PGOPTIONS=$oldOptions;$env:PGSSLMODE=$oldSsl
}
if($success){try{
 $saved=Join-Path $project 'tools\live-ledger-adoption';New-Item -ItemType Directory $saved -Force | Out-Null
 foreach($name in @('verify-and-register.mjs','reviewed-equivalence.mjs','reviewed-equivalence.test.mjs','reviewed-pairs.json')){Copy-Item (Join-Path $payload $name) (Join-Path $saved $name) -Force}
 Copy-Item $PSCommandPath (Join-Path $project 'scripts\completion-live-ledger-adoption.ps1') -Force
 [ordered]@{scope='Controlled working database migration-ledger adoption';reviewedRepresentationPairs=31;comparatorTestsPassed=38;restoredCopyChecksPassed=9;workingDatabaseChecksPassed=9;workingLedgerInstalled=$true;metadataOnlyChange=$true;businessDataChanged=$false;businessFunctionsReplayed=$false;existingPrivilegesUnchanged=$true;businessFingerprintsUnchanged=$true;temporaryDatabasesRemoved=$true;freshBackupVerified=$true;productionFeaturesEnabled=$false;kbzPayDeferred=$true;reportFolder=$report;verifiedAt=(Get-Date -Format o)} | ConvertTo-Json | Set-Content (Join-Path $report 'live-ledger-summary.json') -Encoding UTF8
 Copy-Item (Join-Path $report 'live-ledger-summary.json') (Join-Path $project 'docs\completion\live-ledger-summary.json') -Force
 Write-Host 'PASS: Fresh restored-copy checks (9) and working database checks (9) passed.' -ForegroundColor Green
 Write-Host 'PASS: Working ledger registered; previously absent provisioning metadata installed. Existing functions were not replayed.'
 Write-Host 'PASS: Business schema/data/sequences and privileges unchanged; temporary databases removed.'
 Write-Host 'PENDING: Git/dashboard checkpoint, clean-machine/CI and recovery/MFA/audit production rollout. No .env or application-authentication change.'
}catch{$success=$false;Write-Host ('FAIL: '+$_.Exception.Message) -ForegroundColor Red}}
Write-Host "Reports and private database backup: $report"
Write-Host "Working ledger COMMIT completed: $liveCommitted"
if($createdCopy){Write-Host "Retained restored copy: $copy"};if($createdReference){Write-Host "Retained reference: $reference"}
Write-Host 'No real email, production recovery/MFA/audit activation, Git commit or KBZPay operation. Do not upload database dumps.'
if(-not $success){Write-Host 'Keep reports. Do not assume rollback if COMMIT completed; send the first error.';exit 1}
